  a=s['attempts'][-1];a0=t['attempts'][-1]
  def sig(a):return [(c['execution_state'],c['alternatives']['at_boundary'],c['suspended']['at_boundary']) for c in a['computations']]
  if sig(a)"'!=sig(a0) or a['"'notes'] or x.get('harness_faults'):print(f.relative_to(ROOT),s['stage'],sig(a),a['notes'],x.get('harness_faults'),repr(a['observe']['raw'][:400]))
print('checked',len(rr),'records')
